      expect(f.sleeps.single, const Duration(seconds: 3600));
    });

    test('Retry-After takes precedence over X-RateLimit-Reset', () async {
      final f = _thenOk({
        'retry-after': ['10'],
        'x-ratelimit-reset': [_resetSecondsFromNow(600)],
