    SyncRetryPolicy(
      maxAttempts: maxAttempts,
      baseDelayMs: 1000,
      maxDelayMs: 600,
      backoffMultiplier: 2.0,
      jitterFactor: 0.3,
      rateLimitMaxWaitSeconds: cap,
