_RateLimitFixture _thenOk(Map<String, List<String>> headers, [String body = '{"ok":true}']) {
  var calls = 0;
  return _fixture(
    handler: (_) => ++calls == 1 ? _resp(429, '', headers) : _resp(200, body),
