/// Shared HTTP client base for all REST API integrations.
///
/// Provides common get/post/put/delete methods via dio, with each
/// integration overriding [buildUrl] and [authHeaders].
library;

import 'package:dio/dio.dart';

/// Base class for integration HTTP clients.
abstract class BaseHttpClient {
  /// The underlying dio transport.
  final Dio dio;

  /// The configured base URL for this integration.
  final String basePath;

  /// Creates a client with the given [dio] and [basePath].
  const BaseHttpClient({required this.dio, required this.basePath});

  /// Override to provide integration-specific auth headers.
  Map<String, String> get authHeaders => const {};

  /// Returns all headers (auth + content type).
  Map<String, String> get headers => {
        ...authHeaders,
        'Content-Type': 'application/json',
      };

  /// Builds the full URL for a relative path. Override per integration.
  String buildUrl(String path);

  /// Performs a GET request.
  ///
  /// Pass [extra] to merge additional headers (e.g. a media-type `Accept`)
  /// on top of the integration defaults.
  Future<String> get(
    String path, {
    Map<String, dynamic>? queryParams,
    Map<String, String>? extra,
  }) async {
    final response = await dio.get<String>(
      buildUrl(path),
      queryParameters: queryParams,
      options: Options(headers: {...headers, ...?extra}),
    );
    return response.data ?? '';
  }

  /// Performs a POST request.
  ///
  /// Pass [extra] to merge additional headers (e.g. a CSRF crumb) on top of
  /// the integration defaults.
  Future<String> post(
    String path, {
    Object? body,
    Map<String, String>? extra,
  }) async {
    final response = await dio.post<String>(
      buildUrl(path),
      data: body,
      options: Options(headers: {...headers, ...?extra}),
    );
    return response.data ?? '';
  }

  /// Performs a PUT request.
  Future<String> put(String path, {Object? body}) async {
    final response = await dio.put<String>(
      buildUrl(path),
      data: body,
      options: Options(headers: headers),
    );
    return response.data ?? '';
  }

  /// Performs a PATCH request.
  Future<String> patch(String path, {Object? body}) async {
    final response = await dio.patch<String>(
      buildUrl(path),
      data: body,
      options: Options(headers: headers),
    );
    return response.data ?? '';
  }

  /// Performs a DELETE request.
  Future<String> delete(String path) async {
    final response = await dio.delete<String>(
      buildUrl(path),
      options: Options(headers: headers),
    );
    return response.data ?? '';
  }

  /// Closes the underlying HTTP client.
  void close() => dio.close();

  /// Creates a [Dio] with the standard 60-second timeouts.
  static Dio createDefaultDio() => Dio(
        BaseOptions(
          connectTimeout: const Duration(seconds: 60),
          sendTimeout: const Duration(seconds: 60),
          receiveTimeout: const Duration(seconds: 60),
        ),
      );
}

commit fab5b0ea750ea510fd26926547b35e33854540d3
Author: Uladzimir Klyshevich <Uladzimir_Klyshevich@epam.com>
Date:   Thu Oct 1 11:26:32 2026 +0300

    fix(networking): honor GitHub X-RateLimit-Reset wait instead of capping at 60s (#1)

    ReportGenerator crashed when the GitHub API rate limit was hit: the existing
    retry honored rate limits in name only — the X-RateLimit-Reset delay was capped
    at maxDelayMs (60s) so it never waited for the (up to hourly) reset, and the
    Retry-After branch hard-aborted above 300s. The limit was re-hit, maxRetries
    exhausted, and the RateLimitException killed the whole report, losing all
    already-collected data.

    Fix (RetryPolicy.calculateDelayMs):
    - X-RateLimit-Reset: wait (resetTime - now) + 1s buffer, capped at a new
      configurable cap RATE_LIMIT_MAX_WAIT_SECONDS (default 3600s, via
      PropertyReader), never capped by maxDelayMs and never aborted.
