/// on top; recorded waits land in `sleeps`.
_RateLimitFixture _fixture({
  required ResponseBody Function(RequestOptions options) handler,
  SyncRetryPolicy? policy,
  int maxAttempts = 5,
}) {
  final adapter = _StubAdapter(handler);
