import 'dart:typed_data';
import 'package:dio/dio.dart';
import 'package:dmtools/dmtools.dart';
import 'package:dmtools/src/js/sync_retry_policy.dart';
import 'package:test/test.dart';

class _StubAdapter implements HttpClientAdapter {
  _StubAdapter(this._handler);
  final ResponseBody Function(RequestOptions options) _handler;
  final calls = <RequestOptions>[];
  @override
  Future<ResponseBody> fetch(options, stream, cancelFuture) async {
    calls.add(options);
    return _handler(options);
  }
  @override
  void close({bool force = false}) {}
}

ResponseBody _resp(int status, String body, [Map<String, List<String>> headers = const {}]) =>
    ResponseBody.fromString(body, status, headers: headers);

typedef _F = ({Dio dio, GithubRateLimitRetryInterceptor interceptor, _StubAdapter adapter, List<Duration> sleeps});

SyncRetryPolicy _policy({int maxAttempts = 5, int cap = 3600}) => SyncRetryPolicy(
      maxAttempts: maxAttempts, baseDelayMs: 1000, maxDelayMs: 600,
      backoffMultiplier: 2.0, jitterFactor: 0.3, rateLimitMaxWaitSeconds: cap);

_F _fixture({required ResponseBody Function(RequestOptions options) handler, SyncRetryPolicy? policy, int maxAttempts = 5}) {
  final adapter = _StubAdapter(handler);
  final dio = Dio()..httpClientAdapter = adapter;
  final sleeps = <Duration>[];
  final interceptor = GithubRateLimitRetryInterceptor(
    dio: dio,
    policy: policy ?? _policy(maxAttempts: maxAttempts),
    maxAttempts: maxAttempts,
    sleep: (duration) async => sleeps.add(duration),
  );
  dio.interceptors.add(interceptor);
  return (dio: dio, interceptor: interceptor, adapter: adapter, sleeps: sleeps);
}

void main() {
  test('persistent 429', () async {
    final f = _fixture(handler: (_) => _resp(429, '', {'retry-after': ['1']}));
    try {
      await f.dio.get<String>('https://api.github.com/user');
      print('NO THROW');
    } catch (e) {
      print('caught: ${e.runtimeType}');
      if (e is DioException) print('status: ${e.response?.statusCode}');
    }
    print('calls: ${f.adapter.calls.length}, sleeps: ${f.sleeps.length}');
  });
}
